// Browser-side local-vs-cloud comparison.
//
// Mirrors `compare_local_vs_cloud` in `aihwbench/analysis/cost.py`, which
// stays canonical. Reference cases generated by that function are replayed
// through this one in web/tests, so the site and the CLI cannot answer the
// same question differently.
//
// No cloud pricing is bundled here either. Provider prices change often, and
// a stale table inside a static site would keep producing confident wrong
// answers long after anyone thought to check it. The reader supplies today's
// price.

export interface TcoInputs {
  tokensPerMonth: number | null
  cloudUsdPerMillionTokens: number | null
  hardwareCostUsd: number | null
  electricityUsdPerKwh: number | null
  averagePowerWatts: number | null
  generationTokensPerSecond: number | null
  years: number
}

export interface TcoReport {
  years: number
  cloud_cost_usd: number | null
  cloud_monthly_usd?: number | null
  local_cost_usd: number | null
  local_energy_usd: number | null
  local_monthly_energy_usd?: number | null
  savings_usd: number | null
  break_even_months: number | null
  cheaper: 'local' | 'cloud' | null
  reason?: string
}

function round(value: number, places: number): number {
  const factor = 10 ** places
  return Math.round(value * factor) / factor
}

export function compareLocalVsCloud(inputs: TcoInputs): TcoReport {
  const {
    tokensPerMonth,
    cloudUsdPerMillionTokens,
    hardwareCostUsd,
    electricityUsdPerKwh,
    averagePowerWatts,
    generationTokensPerSecond,
    years,
  } = inputs

  const out: TcoReport = {
    years,
    cloud_cost_usd: null,
    local_cost_usd: null,
    local_energy_usd: null,
    savings_usd: null,
    break_even_months: null,
    cheaper: null,
  }

  if (!tokensPerMonth || tokensPerMonth <= 0) {
    out.reason = 'monthly token volume is required'
    return out
  }
  if (cloudUsdPerMillionTokens === null || cloudUsdPerMillionTokens < 0) {
    out.reason = 'a cloud price per million tokens is required'
    return out
  }

  const months = years * 12
  const cloudMonthly = (tokensPerMonth / 1_000_000) * cloudUsdPerMillionTokens
  out.cloud_cost_usd = round(cloudMonthly * months, 2)
  out.cloud_monthly_usd = round(cloudMonthly, 2)

  // How long the machine must run to produce that many tokens, and what the
  // electricity for that costs.
  let energyMonthly: number | null = null
  if (
    electricityUsdPerKwh &&
    averagePowerWatts !== null &&
    generationTokensPerSecond &&
    generationTokensPerSecond > 0
  ) {
    const seconds = tokensPerMonth / generationTokensPerSecond
    const kwh = (averagePowerWatts / 1000) * (seconds / 3600)
    energyMonthly = kwh * electricityUsdPerKwh
    out.local_energy_usd = round(energyMonthly * months, 2)
    out.local_monthly_energy_usd = round(energyMonthly, 2)
  }

  if (hardwareCostUsd === null) {
    out.reason = 'hardware cost is required to compare against ownership'
    return out
  }

  const localTotal = hardwareCostUsd + (energyMonthly ?? 0) * months
  out.local_cost_usd = round(localTotal, 2)
  out.savings_usd = round(out.cloud_cost_usd - localTotal, 2)
  out.cheaper = localTotal < out.cloud_cost_usd ? 'local' : 'cloud'

  // If running locally does not cost less per month, buying hardware never
  // catches up. Saying "never" is more useful than a figure in the hundreds
  // of months, which reads like a result.
  const monthlyDelta = cloudMonthly - (energyMonthly ?? 0)
  if (monthlyDelta > 0) {
    out.break_even_months = round(hardwareCostUsd / monthlyDelta, 1)
  } else {
    out.break_even_months = null
    out.reason =
      'local running cost is not below the cloud cost at this volume, so buying hardware never pays for itself here'
  }
  return out
}
